class _ContractTemplate {
  final String id;
  final String name;
  final String description;
  final String contractBName;
  final String contractBRole;
  final String contractAName;
  final String contractARole;
  final String abiB;
  final String bytecodeB;
  final String abiA;
  final String bytecodeA;
  final String sourceBTemplate;
  final String sourceATemplate;

  const _ContractTemplate({
    required this.id,
    required this.name,
    required this.description,
    required this.contractBName,
    required this.contractBRole,
    required this.contractAName,
    required this.contractARole,
    required this.abiB,
    required this.bytecodeB,
    required this.abiA,
    required this.bytecodeA,
    required this.sourceBTemplate,
    required this.sourceATemplate,
  });
}

