// ── Solidity source templates ───────────────────────────────────────────────────
const String _valueStoreSrc = '''// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title {NAME} — Value storage contract (Contract B)
contract {NAME} {
    uint256 private _value;
    string public name;
    address public owner;

    event ValueChanged(uint256 newValue, address changedBy);

    constructor(string memory _name) {
        name = _name;
        owner = msg.sender;
    }

    function store(uint256 value) external {
        _value = value;
        emit ValueChanged(value, msg.sender);
    }

    function retrieve() external view returns (uint256) {
        return _value;
    }
}''';

const String _valueProxySrc = '''// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IValueStore {
    function store(uint256 value) external;
    function retrieve() external view returns (uint256);
}

/// @title {NAME} — Proxy contract that delegates to Contract B (Contract A)
contract {NAME} {
    IValueStore public target;
    string public name;
    address public owner;
    uint256 public callCount;

    event ProxyCall(string action, uint256 value);

    constructor(string memory _name, address _targetAddress) {
        name = _name;
        target = IValueStore(_targetAddress);
        owner = msg.sender;
        callCount = 0;
    }

    /// @dev Store value via Contract B and increment call counter
    function proxyStore(uint256 value) external {
        callCount++;
        target.store(value);
        emit ProxyCall("store", value);
    }

    function proxyRetrieve() external view returns (uint256) {
        return target.retrieve();
    }

    function getCallCount() external view returns (uint256) {
        return callCount;
    }
}''';

const String _messageBoardSrc = '''// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title {NAME} — On-chain message board (Contract B)
contract {NAME} {
    string[] private messages;
    address public owner;
    string public boardName;

    event MessagePosted(string message, address poster);

    constructor(string memory _boardName) {
        boardName = _boardName;
        owner = msg.sender;
    }

    function post(string calldata message) external {
        messages.push(message);
        emit MessagePosted(message, msg.sender);
    }

    function getMessageCount() external view returns (uint256) {
        return messages.length;
    }

    function getMessage(uint256 index) external view returns (string memory) {
        require(index < messages.length, "Index out of bounds");
        return messages[index];
    }
}''';

const String _messageBroadcasterSrc = '''// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IMessageBoard {
    function post(string calldata message) external;
    function getMessageCount() external view returns (uint256);
    function getMessage(uint256 index) external view returns (string memory);
}

/// @title {NAME} — Broadcasts messages to Contract B (Contract A)
contract {NAME} {
    IMessageBoard public board;
    string public broadcasterName;
    address public owner;
    uint256 public broadcastCount;

    event Broadcast(string message, uint256 timestamp);

    constructor(string memory _name, address _boardAddress) {
        broadcasterName = _name;
        board = IMessageBoard(_boardAddress);
        owner = msg.sender;
        broadcastCount = 0;
    }

    /// @dev Post message to Contract B's board
    function broadcast(string calldata message) external {
        broadcastCount++;
        board.post(message);
        emit Broadcast(message, block.timestamp);
    }

    function getTotalMessages() external view returns (uint256) {
        return board.getMessageCount();
    }

    function readMessage(uint256 index) external view returns (string memory) {
        return board.getMessage(index);
    }
}''';

const String _scoreBoardSrc = '''// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title {NAME} — On-chain score board (Contract B)
contract {NAME} {
    mapping(address => uint256) private scores;
    address[] private players;
    string public gameName;
    address public owner;

    event ScoreUpdated(address player, uint256 score);

    constructor(string memory _gameName) {
        gameName = _gameName;
        owner = msg.sender;
    }

    function setScore(address player, uint256 score) external {
        if (scores[player] == 0) players.push(player);
        scores[player] = score;
        emit ScoreUpdated(player, score);
    }

    function getScore(address player) external view returns (uint256) {
        return scores[player];
    }

    function getPlayerCount() external view returns (uint256) {
        return players.length;
    }
}''';

const String _scoreManagerSrc = '''// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IScoreBoard {
    function setScore(address player, uint256 score) external;
    function getScore(address player) external view returns (uint256);
    function getPlayerCount() external view returns (uint256);
}

/// @title {NAME} — Score manager that writes to Contract B (Contract A)
contract {NAME} {
    IScoreBoard public scoreBoard;
    string public managerName;
    address public owner;

    event ScoreSubmitted(address player, uint256 score, address submitter);

    constructor(string memory _name, address _scoreBoardAddress) {
        managerName = _name;
        scoreBoard = IScoreBoard(_scoreBoardAddress);
        owner = msg.sender;
    }

    /// @dev Submit a score to Contract B's board
    function submitScore(address player, uint256 score) external {
        scoreBoard.setScore(player, score);
        emit ScoreSubmitted(player, score, msg.sender);
    }

    function queryScore(address player) external view returns (uint256) {
        return scoreBoard.getScore(player);
    }

    function getPlayerCount() external view returns (uint256) {
        return scoreBoard.getPlayerCount();
    }
}''';

