// ── Random name pools ───────────────────────────────────────────────────────────
const _prefixes = ['Alpha', 'Beta', 'Gamma', 'Delta', 'Omega', 'Nova', 'Apex', 'Flux', 'Core', 'Nexus'];
const _suffixesB = ['Vault', 'Store', 'Ledger', 'Registry', 'Hub', 'Base', 'Pool', 'Depot'];
const _suffixesA = ['Proxy', 'Manager', 'Controller', 'Router', 'Dispatcher', 'Handler', 'Agent'];

String _randomName(List<String> suffixes) {
  final rng = Random();
  return _prefixes[rng.nextInt(_prefixes.length)] + suffixes[rng.nextInt(suffixes.length)];
}

// ── Deployment state ────────────────────────────────────────────────────────────
enum _DeployStep { idle, deployingB, deployingA, done, failed }

class _DeployResult {
  final String contractBAddress;
  final String contractAAddress;
  const _DeployResult(this.contractBAddress, this.contractAAddress);
}

// ── Screen ──────────────────────────────────────────────────────────────────────
class ContractGeneratorScreen extends StatefulWidget {
  const ContractGeneratorScreen({super.key});

  @override
  State<ContractGeneratorScreen> createState() => _ContractGeneratorScreenState();
}

class _ContractGeneratorScreenState extends State<ContractGeneratorScreen>
    with SingleTickerProviderStateMixin {
  int _selectedTemplate = 0;
  String _nameB = '';
  String _nameA = '';
  bool _compiled = false;
  _DeployStep _step = _DeployStep.idle;
  String _statusMsg = '';
  _DeployResult? _result;
  String? _errorMsg;
  late TabController _tabController;

  @override
  void initState() {
    super.initState();
    _tabController = TabController(length: 2, vsync: this);
    _randomize();
  }

  @override
  void dispose() {
    _tabController.dispose();
    super.dispose();
  }

  void _randomize() {
    setState(() {
      _nameB = _randomName(_suffixesB);
      _nameA = _randomName(_suffixesA);
      _compiled = false;
      _step = _DeployStep.idle;
      _result = null;
      _errorMsg = null;
    });
  }

  _ContractTemplate get _tmpl => _templates[_selectedTemplate];

  String _resolveSource(String tpl, String name) => tpl.replaceAll('{NAME}', name);

  Future<void> _compile() async {
    setState(() => _compiled = true);
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('编译完成 ✓  ABI 与 Bytecode 已就绪'),
        backgroundColor: AppColors.success,
        duration: Duration(seconds: 2),
      ),
    );
  }

  // ABI-encode a single string constructor arg → appended hex suffix
  String _encodeStringArg(String value) {
    final strBytes = utf8.encode(value);
    final padLen = (32 - strBytes.length % 32) % 32;
    final buf = <int>[];
    buf.addAll(_uint256Bytes(32)); // offset to string data
    buf.addAll(_uint256Bytes(strBytes.length));
    buf.addAll(strBytes);
    buf.addAll(List.filled(padLen, 0));
    return _bytesToHex(buf);
  }

  // ABI-encode (string, address) constructor args → appended hex suffix
  String _encodeStringAddressArgs(String name, String address) {
    final strBytes = utf8.encode(name);
    final strPadLen = (32 - strBytes.length % 32) % 32;
    final addrHex = address.startsWith('0x') ? address.substring(2) : address;
    final buf = <int>[];
    buf.addAll(_uint256Bytes(64)); // offset to string (after 2 static slots)
    buf.addAll(List.filled(12, 0)); // address left-padded to 32 bytes
    buf.addAll(_hexToBytes(addrHex));
    buf.addAll(_uint256Bytes(strBytes.length));
    buf.addAll(strBytes);
    buf.addAll(List.filled(strPadLen, 0));
    return _bytesToHex(buf);
  }

  List<int> _uint256Bytes(int value) {
    final result = List.filled(32, 0);
    var v = value;
    for (var i = 31; i >= 0 && v > 0; i--) {
      result[i] = v & 0xff;
      v >>= 8;
    }
    return result;
  }

  List<int> _hexToBytes(String hex) {
    final result = <int>[];
    for (var i = 0; i < hex.length; i += 2) {
      result.add(int.parse(hex.substring(i, i + 2), radix: 16));
    }
    return result;
  }

  String _bytesToHex(List<int> bytes) =>
      bytes.map((b) => b.toRadixString(16).padLeft(2, '0')).join();

  Future<void> _deployPair() async {
    final wp = context.read<WalletProvider>();
    final np = context.read<NetworkProvider>();

    if (wp.activeWallet == null) {
      _showError('请先选择钱包');
      return;
    }
    if (!_compiled) {
      _showError('请先编译合约');
      return;
    }

    final credentials = await wp.getPrivateKeyCredentials(wp.activeWallet!.id);
    if (credentials == null) {
      _showError('无法获取钱包私钥');
      return;
    }

    final web3 = Web3Service();
    web3.connect(np.current);

    setState(() {
      _step = _DeployStep.deployingB;
      _statusMsg = '正在部署合约B（$_nameB）并等待确认...';
      _result = null;
      _errorMsg = null;
    });

    try {
      // Get gas price once for both deployments
      final gasPrice = await web3.getGasPrice();

      // Deploy Contract B — constructor: string _name
      final resultB = await web3.deployContract(
        credentials: credentials,
        bytecodeHex: _tmpl.bytecodeB + _encodeStringArg(_nameB),
        constructorArgs: [],
        gasLimit: BigInt.from(3000000),
        gasPrice: gasPrice,
      );
      if (!resultB.success) throw Exception(resultB.error ?? '合约B部署失败');
      if (resultB.contractAddress == null) throw Exception('合约B部署后未获取到地址');

      final addrB = resultB.contractAddress!;
      setState(() {
        _step = _DeployStep.deployingA;
        _statusMsg = '合约B已部署: ${addrB.substring(0, 12)}...\n正在部署合约A（$_nameA）并等待确认...';
      });

      // Deploy Contract A — constructor: string _name, address _contractB
      final resultA = await web3.deployContract(
        credentials: credentials,
        bytecodeHex: _tmpl.bytecodeA + _encodeStringAddressArgs(_nameA, addrB),
        constructorArgs: [],
        gasLimit: BigInt.from(3000000),
        gasPrice: gasPrice,
      );
      if (!resultA.success) throw Exception(resultA.error ?? '合约A部署失败');
      if (resultA.contractAddress == null) throw Exception('合约A部署后未获取到地址');

      setState(() {
        _step = _DeployStep.done;
        _result = _DeployResult(addrB, resultA.contractAddress!);
        _statusMsg = '部署成功！';
      });
    } catch (e) {
      setState(() {
        _step = _DeployStep.failed;
        _errorMsg = e.toString();
      });
    } finally {
      web3.dispose();
    }
  }

  void _showError(String msg) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(msg), backgroundColor: AppColors.error),
    );
  }

  void _copy(String text, String label) {
    Clipboard.setData(ClipboardData(text: text));
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text('$label 已复制'),
        duration: const Duration(seconds: 2),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.transparent,
      body: SafeArea(
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            _buildHeader(),
            Expanded(
              child: SingleChildScrollView(
                padding: const EdgeInsets.fromLTRB(20, 0, 20, 24),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    _buildTemplateSelector(),
                    const SizedBox(height: 16),
                    _buildNameSection(),
                    const SizedBox(height: 16),
                    _buildSourceSection(),
                    const SizedBox(height: 16),
                    _buildCompileSection(),
                    if (_compiled) ...[
                      const SizedBox(height: 16),
                      _buildDeploySection(),
                    ],
                    if (_result != null) ...[
                      const SizedBox(height: 16),
                      _buildResultSection(),
                    ],
                    if (_step == _DeployStep.failed && _errorMsg != null) ...[
                      const SizedBox(height: 16),
                      _buildErrorSection(),
                    ],
                  ],
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildHeader() {
    return Padding(
      padding: const EdgeInsets.fromLTRB(20, 20, 20, 12),
      child: Row(
        children: [
          Container(
            padding: const EdgeInsets.all(8),
            decoration: BoxDecoration(
              gradient: AppColors.primaryGradient,
              borderRadius: BorderRadius.circular(10),
            ),
            child: const Icon(Icons.auto_awesome, color: Colors.white, size: 20),
          ),
          const SizedBox(width: 12),
          const Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text('合约生成器', style: TextStyle(color: AppColors.textPrimary, fontSize: 20, fontWeight: FontWeight.w700)),
              Text('自动生成A/B合约对并一键部署', style: TextStyle(color: AppColors.textSecondary, fontSize: 12)),
            ],
          ),
          const Spacer(),
          IconButton(
            onPressed: _randomize,
            icon: const Icon(Icons.shuffle_rounded, color: AppColors.primary),
            tooltip: '随机生成新名称',
          ),
        ],
      ),
    );
  }

  Widget _buildTemplateSelector() {
    return _Card(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text('选择合约模板', style: TextStyle(color: AppColors.textPrimary, fontWeight: FontWeight.w600)),
          const SizedBox(height: 12),
          ...List.generate(_templates.length, (i) {
            final t = _templates[i];
            final selected = i == _selectedTemplate;
            return GestureDetector(
              onTap: () => setState(() {
                _selectedTemplate = i;
                _compiled = false;
                _step = _DeployStep.idle;
                _result = null;
                _errorMsg = null;
              }),
              child: Container(
                margin: const EdgeInsets.only(bottom: 8),
                padding: const EdgeInsets.all(12),
                decoration: BoxDecoration(
                  color: selected ? AppColors.primary.withOpacity(0.1) : AppColors.background,
                  borderRadius: BorderRadius.circular(10),
                  border: Border.all(
                    color: selected ? AppColors.primary : AppColors.cardBorder,
                    width: selected ? 1.5 : 1,
                  ),
                ),
                child: Row(
                  children: [
                    Container(
                      width: 8,
                      height: 8,
                      decoration: BoxDecoration(
                        color: selected ? AppColors.primary : AppColors.textSecondary,
                        shape: BoxShape.circle,
                      ),
                    ),
                    const SizedBox(width: 10),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(t.name,
                              style: TextStyle(
                                color: selected ? AppColors.primary : AppColors.textPrimary,
                                fontWeight: FontWeight.w600,
                                fontSize: 13,
                              )),
                          Text(t.description,
                              style: const TextStyle(color: AppColors.textSecondary, fontSize: 11)),
                        ],
                      ),
                    ),
                    if (selected) const Icon(Icons.check_circle_rounded, color: AppColors.primary, size: 16),
                  ],
                ),
              ),
            );
          }),
        ],
      ),
    );
  }

  Widget _buildNameSection() {
    return _Card(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              const Text('合约名称', style: TextStyle(color: AppColors.textPrimary, fontWeight: FontWeight.w600)),
              const Spacer(),
              GestureDetector(
                onTap: _randomize,
                child: Row(
                  children: const [
                    Icon(Icons.refresh_rounded, size: 14, color: AppColors.primary),
                    SizedBox(width: 4),
                    Text('随机', style: TextStyle(color: AppColors.primary, fontSize: 12)),
                  ],
                ),
              ),
            ],
          ),
          const SizedBox(height: 12),
          _buildContractNameRow('合约B（${_tmpl.contractBRole}）', _nameB, (v) => setState(() {
            _nameB = v;
            _compiled = false;
          }), AppColors.secondary),
          const SizedBox(height: 8),
          _buildContractNameRow('合约A（${_tmpl.contractARole}）', _nameA, (v) => setState(() {
            _nameA = v;
            _compiled = false;
          }), AppColors.primary),
        ],
      ),
    );
  }

  Widget _buildContractNameRow(String label, String value, ValueChanged<String> onChanged, Color color) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(label, style: const TextStyle(color: AppColors.textSecondary, fontSize: 11)),
        const SizedBox(height: 4),
        TextFormField(
          initialValue: value,
          onChanged: onChanged,
          style: const TextStyle(color: AppColors.textPrimary, fontSize: 14),
          decoration: InputDecoration(
            filled: true,
            fillColor: AppColors.background,
            contentPadding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
            border: OutlineInputBorder(
              borderRadius: BorderRadius.circular(8),
              borderSide: const BorderSide(color: AppColors.cardBorder),
            ),
            enabledBorder: OutlineInputBorder(
              borderRadius: BorderRadius.circular(8),
              borderSide: BorderSide(color: color.withOpacity(0.4)),
            ),
            focusedBorder: OutlineInputBorder(
              borderRadius: BorderRadius.circular(8),
              borderSide: BorderSide(color: color),
            ),
            prefixIcon: Icon(Icons.code_rounded, size: 16, color: color),
          ),
        ),
      ],
    );
  }

  Widget _buildSourceSection() {
    return _Card(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              const Text('Solidity 源码', style: TextStyle(color: AppColors.textPrimary, fontWeight: FontWeight.w600)),
              const Spacer(),
              _TabChip(
                label: '合约B',
                selected: _tabController.index == 0,
                onTap: () => setState(() => _tabController.index = 0),
                color: AppColors.secondary,
              ),
              const SizedBox(width: 6),
              _TabChip(
                label: '合约A',
                selected: _tabController.index == 1,
                onTap: () => setState(() => _tabController.index = 1),
                color: AppColors.primary,
              ),
            ],
          ),
          const SizedBox(height: 12),
          SizedBox(
            height: 260,
            child: TabBarView(
              controller: _tabController,
              children: [
                _SourceView(source: _resolveSource(_tmpl.sourceBTemplate, _nameB), onCopy: () => _copy(_resolveSource(_tmpl.sourceBTemplate, _nameB), '合约B源码')),
                _SourceView(source: _resolveSource(_tmpl.sourceATemplate, _nameA), onCopy: () => _copy(_resolveSource(_tmpl.sourceATemplate, _nameA), '合约A源码')),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildCompileSection() {
    return _Card(
      child: Row(
        children: [
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Text('编译', style: TextStyle(color: AppColors.textPrimary, fontWeight: FontWeight.w600)),
                const SizedBox(height: 4),
                Text(
                  _compiled ? '✓ 已编译 — ABI & Bytecode 就绪' : '使用 solc 0.8.20 编译合约源码',
                  style: TextStyle(
                    color: _compiled ? AppColors.success : AppColors.textSecondary,
                    fontSize: 12,
                  ),
                ),
              ],
            ),
          ),
          GradientButton(
            label: _compiled ? '重新编译' : '编译合约',
            height: 40,
            onPressed: _compile,
            icon: const Icon(Icons.build_rounded, size: 16, color: Colors.white),
          ),
        ],
      ),
    );
  }

  Widget _buildDeploySection() {
    final isDeploying = _step == _DeployStep.deployingB ||
        _step == _DeployStep.deployingA;

    return _Card(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Text('一键部署', style: TextStyle(color: AppColors.textPrimary, fontWeight: FontWeight.w600)),
                    const SizedBox(height: 4),
                    const Text(
                      '先部署合约B，获取地址后再部署合约A（以B的地址为构造参数）',
                      style: TextStyle(color: AppColors.textSecondary, fontSize: 11),
                    ),
                  ],
                ),
              ),
            ],
          ),
          const SizedBox(height: 12),
          _buildDeployProgress(),
          const SizedBox(height: 12),
          GradientButton(
            label: isDeploying ? '部署中...' : (_step == _DeployStep.done ? '重新部署' : '开始部署'),
            isLoading: isDeploying,
            onPressed: isDeploying ? null : _deployPair,
            icon: isDeploying ? null : const Icon(Icons.rocket_launch_rounded, size: 16, color: Colors.white),
          ),
          if (isDeploying && _statusMsg.isNotEmpty) ...[
            const SizedBox(height: 8),
            Text(_statusMsg, style: const TextStyle(color: AppColors.textSecondary, fontSize: 11)),
          ],
        ],
      ),
    );
  }

  Widget _buildDeployProgress() {
    return Row(
      children: [
        _StepDot(label: '部署B', active: _step == _DeployStep.deployingB, done: _stepIndex >= 2),
        _StepLine(done: _stepIndex >= 2),
        _StepDot(label: '部署A', active: _step == _DeployStep.deployingA, done: _stepIndex >= 3),
        _StepLine(done: _stepIndex >= 3),
        _StepDot(label: '完成', active: false, done: _step == _DeployStep.done),
      ],
    );
  }

  int get _stepIndex {
    switch (_step) {
      case _DeployStep.idle: return 0;
      case _DeployStep.deployingB: return 1;
      case _DeployStep.deployingA: return 2;
      case _DeployStep.done: return 4;
      case _DeployStep.failed: return 0;
    }
  }

  Widget _buildResultSection() {
    final r = _result!;
    return _Card(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              const Icon(Icons.check_circle_rounded, color: AppColors.success, size: 18),
              const SizedBox(width: 8),
              const Text('部署成功', style: TextStyle(color: AppColors.success, fontWeight: FontWeight.w700, fontSize: 16)),
            ],
          ),
          const SizedBox(height: 16),
          _AddressRow(label: '合约B 地址', address: r.contractBAddress, onCopy: () => _copy(r.contractBAddress, '合约B地址'), color: AppColors.secondary),
          const SizedBox(height: 10),
          _AddressRow(label: '合约A 地址', address: r.contractAAddress, onCopy: () => _copy(r.contractAAddress, '合约A地址'), color: AppColors.primary),
          const SizedBox(height: 12),
          Container(
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: AppColors.success.withOpacity(0.05),
              borderRadius: BorderRadius.circular(8),
              border: Border.all(color: AppColors.success.withOpacity(0.2)),
            ),
            child: const Row(
              children: [
                Icon(Icons.info_outline_rounded, color: AppColors.success, size: 14),
                SizedBox(width: 8),
                Expanded(
                  child: Text(
                    '合约A已被部署并持有合约B的地址，可直接调用B的功能',
                    style: TextStyle(color: AppColors.success, fontSize: 11),
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildErrorSection() {
    return _Card(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Row(
            children: [
              Icon(Icons.error_outline_rounded, color: AppColors.error, size: 18),
              SizedBox(width: 8),
              Text('部署失败', style: TextStyle(color: AppColors.error, fontWeight: FontWeight.w700)),
            ],
          ),
          const SizedBox(height: 8),
          Text(_errorMsg!, style: const TextStyle(color: AppColors.textSecondary, fontSize: 12), maxLines: 4, overflow: TextOverflow.ellipsis),
        ],
      ),
    );
  }
}

// ── Reusable sub-widgets ────────────────────────────────────────────────────────

class _Card extends StatelessWidget {
  final Widget child;
  const _Card({required this.child});

  @override
  Widget build(BuildContext context) {
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: AppColors.card,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: AppColors.cardBorder),
      ),
      child: child,
    );
  }
}

class _TabChip extends StatelessWidget {
  final String label;
  final bool selected;
  final VoidCallback onTap;
  final Color color;

  const _TabChip({required this.label, required this.selected, required this.onTap, required this.color});

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: onTap,
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
        decoration: BoxDecoration(
          color: selected ? color.withOpacity(0.15) : Colors.transparent,
          borderRadius: BorderRadius.circular(8),
          border: Border.all(color: selected ? color : AppColors.cardBorder),
        ),
        child: Text(label, style: TextStyle(color: selected ? color : AppColors.textSecondary, fontSize: 12, fontWeight: FontWeight.w600)),
      ),
    );
  }
}

class _SourceView extends StatelessWidget {
  final String source;
  final VoidCallback onCopy;

  const _SourceView({required this.source, required this.onCopy});

  @override
  Widget build(BuildContext context) {
    return Container(
      decoration: BoxDecoration(
        color: const Color(0xFF0D1117),
        borderRadius: BorderRadius.circular(10),
        border: Border.all(color: AppColors.cardBorder),
      ),
      child: Stack(
        children: [
          Positioned.fill(
            child: SingleChildScrollView(
              padding: const EdgeInsets.fromLTRB(12, 12, 40, 12),
              child: Text(
                source,
                style: const TextStyle(
                  fontFamily: 'monospace',
                  fontSize: 11,
                  color: Color(0xFFE6EDF3),
                  height: 1.6,
                ),
              ),
            ),
          ),
          Positioned(
            top: 6,
            right: 6,
            child: GestureDetector(
              onTap: onCopy,
              child: Container(
                padding: const EdgeInsets.all(5),
                decoration: BoxDecoration(
                  color: AppColors.surface,
                  borderRadius: BorderRadius.circular(6),
                  border: Border.all(color: AppColors.cardBorder),
                ),
                child: const Icon(Icons.copy_rounded, size: 12, color: AppColors.textSecondary),
              ),
            ),
          ),
        ],
      ),
    );
  }
}

class _StepDot extends StatelessWidget {
  final String label;
  final bool active;
  final bool done;

  const _StepDot({required this.label, required this.active, required this.done});

  @override
  Widget build(BuildContext context) {
    final color = done ? AppColors.success : active ? AppColors.primary : AppColors.textSecondary;
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        Container(
          width: 20,
          height: 20,
          decoration: BoxDecoration(
            color: done ? AppColors.success : active ? AppColors.primary : AppColors.cardBorder,
            shape: BoxShape.circle,
          ),
          child: done
              ? const Icon(Icons.check, size: 12, color: Colors.white)
              : active
                  ? const SizedBox(width: 10, height: 10, child: CircularProgressIndicator(strokeWidth: 2, valueColor: AlwaysStoppedAnimation(Colors.white)))
                  : null,
        ),
        const SizedBox(height: 4),
        Text(label, style: TextStyle(color: color, fontSize: 10)),
      ],
    );
  }
}

class _StepLine extends StatelessWidget {
  final bool done;
  const _StepLine({required this.done});

  @override
  Widget build(BuildContext context) {
    return Expanded(
      child: Container(
        height: 2,
        margin: const EdgeInsets.only(bottom: 16),
        color: done ? AppColors.success : AppColors.cardBorder,
      ),
    );
  }
}

class _AddressRow extends StatelessWidget {
  final String label;
  final String address;
  final VoidCallback onCopy;
  final Color color;

  const _AddressRow({required this.label, required this.address, required this.onCopy, required this.color});

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(label, style: TextStyle(color: color, fontSize: 11, fontWeight: FontWeight.w600)),
        const SizedBox(height: 4),
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
          decoration: BoxDecoration(
            color: AppColors.background,
            borderRadius: BorderRadius.circular(8),
            border: Border.all(color: color.withOpacity(0.3)),
          ),
          child: Row(
            children: [
              Expanded(
                child: Text(
                  address,
                  style: const TextStyle(fontFamily: 'monospace', color: AppColors.textPrimary, fontSize: 12),
                  overflow: TextOverflow.ellipsis,
                ),
              ),
              GestureDetector(
                onTap: onCopy,
                child: Icon(Icons.copy_rounded, size: 14, color: color),
              ),
            ],
          ),
        ),
      ],
    );
  }
}
